16: const TIMEOUT_MS = 20_000;
17: 
18: /**
19:  * The answer levels for every column, from against to for. A column can count
20:  * against a customer as well as for one: high incomes suit an affluent
21:  * audience and not a low-income one, and median age points opposite ways for
22:  * young and older audiences. So the level keeps its direction, and the weight
23:  * runs from -1 to 1.
24:  */
25: const LEVELS = [
26:   "Strongly against: the target customers are much less likely to have this trait.",
27:   "Against: the target customers are somewhat less likely to have this trait.",
28:   "Not relevant: the description says nothing either way about this trait.",
29:   "For: the target customers are somewhat more likely to have this trait.",
30:   "Strongly for: the target customers are much more likely to have this trait.",
31: ];
32: 
33: /**
34:  * The answer as a weight from -1 to 1. With per-level probabilities this is
35:  * the expected level, so a split between "for" and "strongly for" lands
36:  * between them; otherwise it is the single level Jev chose.
37:  */
38: function toWeight(answer: { score: number; probabilities?: Record<string, number> }) {
39:   const top = LEVELS.length - 1;
40:   let level = answer.score;
41:   const entries = Object.entries(answer.probabilities ?? {})
42:     .map(([key, p]) => [Number(key), p] as const)
43:     .filter(([i, p]) => Number.isInteger(i) && i >= 0 && i <= top && Number.isFinite(p));
44:   const total = entries.reduce((sum, [, p]) => sum + p, 0);
45:   if (total > 0) level = entries.reduce((sum, [i, p]) => sum + i * p, 0) / total;
46:   return Number(Math.max(-1, Math.min(1, (level / top) * 2 - 1)).toFixed(2));
47: }
