49: async function jevWeights(columns: TractColumn[], brief: Brief): Promise<ColumnWeight[]> {
50:   const result = await decide({
51:     model: getAudienceModel(),
52:     state: {
53:       "target customer": brief.targetCustomer,
54:       startup: brief.description,
55:       industry: brief.industry,
56:     },
57:     questions: Object.fromEntries(
58:       columns.map((c) => [
59:         c.name,
60:         {
61:           type: "score" as const,
62:           instructions: `How does this trait of an area's ${c.measures === "lives" ? "residents" : c.measures === "works" ? "workers" : "passers-by"} relate to the startup's target customers? Trait: ${c.description}.`,
63:           criteria: LEVELS,
64:         },
65:       ]),
66:     ),
67:     abortSignal: AbortSignal.timeout(TIMEOUT_MS),
68:   });
69: 
70:   return columns.map((c) => {
71:     const answer = result.answers[c.name];
72:     if (answer?.type !== "score") throw new Error(`Jev returned no score for "${c.name}".`);
73:     return { column: c.name, description: c.description, measures: c.measures, weight: toWeight(answer) };
74:   });
75: }
